"""Command-line transport and the literal, line-buffered interactive protocol."""

from __future__ import annotations

import argparse
import sys

from . import Connection, DataIOError, MiniSQLError, connect, format_csv, format_table


_HELP = """Commands:
  .help              Show this help
  .tables            List tables
  .schema NAME       Show column names and types
  .format csv|table  Change result format
  .quit / .exit      Exit
Enter SQL ending in a semicolon; unfinished SQL runs at EOF.
"""


def _report_error(error: MiniSQLError) -> None:
    sys.stderr.write(f"{error}\n")


def _execute(connection: Connection, sql: str, output_format: str) -> None:
    formatter = format_csv if output_format == "csv" else format_table
    text = formatter(connection.execute(sql))
    sys.stdout.write(text)


def _repl(connection: Connection, output_format: str) -> int:
    buffer = []
    while True:
        sys.stdout.write("   ...> " if buffer else "minisql> ")
        sys.stdout.flush()
        line = sys.stdin.readline()
        eof = line == ""
        try:
            if eof:
                if buffer:
                    _execute(connection, "\n".join(buffer), output_format)
                return 0
            if line.endswith("\n"):
                line = line[:-1]
            if not buffer:
                text = line.strip()
                if not text:
                    continue
                if text.startswith("."):
                    parts = text.split()
                    if parts in ([".quit"], [".exit"]):
                        return 0
                    if parts == [".help"]:
                        sys.stdout.write(_HELP)
                    elif parts == [".tables"]:
                        for table in connection.tables():
                            sys.stdout.write(f"{table}\n")
                    elif parts[0] == ".schema" and len(parts) == 2:
                        schema = connection.schema(parts[1])
                        for name, kind in schema:
                            sys.stdout.write(f"{name} {kind}\n")
                    elif (parts[0] == ".format" and len(parts) == 2
                          and parts[1] in ("csv", "table")):
                        output_format = parts[1]
                    else:
                        sys.stderr.write(f"unknown command: {text}\n")
                    continue
            buffer.append(line)
            sql = "\n".join(buffer)
            if sql.rstrip().endswith(";"):
                _execute(connection, sql, output_format)
                buffer.clear()
        except MiniSQLError as error:
            _report_error(error)
            buffer.clear()
            if eof:
                return 0


def main(argv: list[str] | None = None) -> int:
    """Run the CLI, configuring only its output streams, never at import time."""
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, "reconfigure"):
            stream.reconfigure(encoding="utf-8", newline="\n")
    parser = argparse.ArgumentParser(prog="minisql", description="Query CSV files with SQL.")
    parser.add_argument("--data", default=".", metavar="DIR")
    parser.add_argument("--format", choices=("csv", "table"))
    parser.add_argument("sql", nargs="?", metavar="SQL")
    args = parser.parse_args(argv)
    try:
        connection = connect(args.data)
        if args.sql is None:
            return _repl(connection, args.format or "table")
        _execute(connection, args.sql, args.format or "csv")
        return 0
    except MiniSQLError as error:
        _report_error(error)
        return 3 if isinstance(error, DataIOError) else 1
